manageAppConfiguration()
    .then(() => {
        console.log("\nRunning conditional update example...");
        return conditionalUpdate();
    })
    .then(() => {
        console.log("\n✓ All demos completed successfully");
    })
    .catch(error => {
        console.error("Fatal error:", error);
        process.exit(1);
    });
